class Solution {
    fun countCompleteSubarrays(nums:IntArray):Int{
        val required=nums.toSet().size;
        val frequency=HashMap<Int,Int>();
        var distinct=0;
        var left=0;
        var answer=0;
        for(value in nums){
            val count=frequency[value]?:0;
            if(count==0)distinct++;
            frequency[value]=count+1;
            while(distinct==required){
                val removed=nums[left++];
                val remaining=frequency[removed]!!-1;
                frequency[removed]=remaining;
                if(remaining==0)distinct--
            };
            answer+=left
        };
        return answer
    }
}

